CREATE DATABASE IF NOT EXISTS servispro CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE servispro;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','kasir','teknisi') NOT NULL DEFAULT 'teknisi',active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE customers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,phone VARCHAR(30),address VARCHAR(255),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(name),INDEX(phone)) ENGINE=InnoDB;
CREATE TABLE tickets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_no VARCHAR(40) UNIQUE NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,device VARCHAR(150) NOT NULL,serial_number VARCHAR(100),complaint TEXT NOT NULL,diagnosis TEXT,technician_id BIGINT UNSIGNED,status ENUM('Diterima','Diagnosa','Menunggu','Dikerjakan','Selesai','Diambil','Dibatalkan') DEFAULT 'Diterima',estimated_cost DECIMAL(14,2) DEFAULT 0,final_cost DECIMAL(14,2) DEFAULT 0,notes TEXT,received_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(technician_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(status),INDEX(customer_id)) ENGINE=InnoDB;
CREATE TABLE parts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,category VARCHAR(100),stock INT DEFAULT 0,min_stock INT DEFAULT 0,buy_price DECIMAL(14,2) DEFAULT 0,sell_price DECIMAL(14,2) DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE ticket_parts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT UNSIGNED NOT NULL,part_id BIGINT UNSIGNED NOT NULL,qty INT NOT NULL,price DECIMAL(14,2) NOT NULL,FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE,FOREIGN KEY(part_id) REFERENCES parts(id)) ENGINE=InnoDB;
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(14,2) NOT NULL,method ENUM('cash','transfer','qris','other') DEFAULT 'cash',paid_at DATETIME DEFAULT CURRENT_TIMESTAMP,received_by BIGINT UNSIGNED,FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE,FOREIGN KEY(received_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,action VARCHAR(100) NOT NULL,detail VARCHAR(500),ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(190),ip_address VARCHAR(45),attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(attempted_at),INDEX(username)) ENGINE=InnoDB;
CREATE TABLE settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT);
INSERT INTO settings VALUES('store_name','ServisPro Computer'),('store_phone',''),('store_address',''),('ticket_prefix','SRV'),('receipt_footer','Terima kasih telah menggunakan layanan kami.');
